package zw.co.hyperfeeds.bookings;
import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Component class BookingExpiryJob{private final JdbcClient jdbc;BookingExpiryJob(JdbcClient j){jdbc=j;}@Scheduled(fixedDelayString="${hyperfeeds.bookings.expiry-scan-delay:60000}")@Transactional void releaseExpired(){List<Map<String,Object>>expired=jdbc.sql("select id,batch_id,quantity from chick_bookings where status='HELD' and expires_at<now() for update skip locked").query().listOfRows();for(var b:expired){jdbc.sql("update chick_bookings set status='EXPIRED',updated_at=now() where id=:id").param("id",b.get("id")).update();jdbc.sql("update chick_batches set reserved_quantity=reserved_quantity-:q where id=:id").param("q",b.get("quantity")).param("id",b.get("batch_id")).update();}}}
